def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    hat_patches = image_patch.find("hat")
    bench_patches = image_patch.find("bench")
    guy_patches = image_patch.find("guy")

    if not hat_patches or not bench_patches or not guy_patches:
        return image_patch

    hat_centers = [(h.left + h.right) / 2 for h in hat_patches]
    bench_centers = [(b.left + b.right) / 2 for b in bench_patches]
    guy_centers = [(g.left + g.right) / 2 for g in guy_patches]

    min_distance = float('inf')
    best_hat = None

    for hat, hat_center in zip(hat_patches, hat_centers):
        for bench, bench_center in zip(bench_patches, bench_centers):
            for guy, guy_center in zip(guy_patches, guy_centers):
                dist = abs(hat_center - bench_center) + abs(hat_center - guy_center)
                if dist < min_distance:
                    min_distance = dist
                    best_hat = hat

    return best_hat

