    image_patch = ImagePatch(image)
    computer_patches = image_patch.find("computer")
    dude_patches = image_patch.find("dude")

    if not computer_patches or not dude_patches:
        return image_patch

    computer_dudes = []
    for comp in computer_patches:
        for dude in dude_patches:
            if distance(comp, dude) < 0.1:  # Assuming a small threshold for proximity
                computer_dudes.append((comp, dude))

    if not computer_dudes:
        return image_patch

    # Find the computer that has the closest dude
    closest_computer = min(computer_dudes, key=lambda x: distance(x[0], x[1]))
    return closest_computer[0]

